// Canonical public questionnaire schema. The website copy is generated by
// scripts/sync-group-feedback-site.mjs; never maintain a second option table.
export const SURVEY_ID = 'hcf-group-class-v1';
export const SURVEY_URL = 'https://www.hsinchucombat.com/group-feedback';
export const SURVEY_VERSION = 1;
export const RATING_QUESTIONS = [
  ['goal','我知道這堂課想讓我學會什麼'],
  ['feedback','教練有給我做得到的具體調整'],
  ['progress','我能說出自己最近進步的地方'],
  ['belonging','我感覺自己是團課的一份子'],
  ['questions','我不懂時，能自在地向教練提問'],
];
export const RATING_OPTIONS = [['1','非常不同意'],['2','不同意'],['3','普通'],['4','同意'],['5','非常同意'],['na','無法判斷']];
export const OPTIONS = {
  attendance: [['none','0 次，回想最近一次'],['some','1–3 次'],['often','4 次以上']],
  atmosphere: [['quiet','安靜專注，教練適時指導'],['gentle','適度互動，但不想被公開點名'],['energetic','熱血鼓勵，喜歡一起加油'],['flexible','依當天內容調整'],['any','沒有特別偏好']],
  activities: [['opening','開場用一句話說明今天的目標'],['peer','夥伴練習後給一句具體鼓勵'],['review','教練在結尾帶大家回顧學到什麼'],['greeting','自願碰拳或點頭，謝謝今天的夥伴'],['team','不排名的團隊小挑戰，內容由教練安排'],['none','暫時不想增加互動']],
  priority: [['clarity','教學說明更清楚'],['attention','教練個別指導更多'],['connection','學員互動更自然'],['pace','課程節奏與強度更合適'],['progress','更清楚看見自己的進步'],['none','目前沒有特別需要改善'],['other','其他，寫在下方']],
};
export const FIELD_LABELS = {attendance:'最近四週上課次數',...Object.fromEntries(RATING_QUESTIONS),atmosphere:'偏好的上課氣氛',activities:'想嘗試的安排',discomfort:'不自在的互動',priority:'希望先改善的事',keep:'值得保留的時刻',change:'希望不同的事',memberName:'姓名或暱稱'};
export const FIELD_ORDER = ['attendance',...RATING_QUESTIONS.map(([key])=>key),'atmosphere','activities','discomfort','priority','keep','change','memberName'];
const fail=message=>{throw Object.assign(new Error(message),{status:400})};
const plain=o=>o!==null&&typeof o==='object'&&!Array.isArray(o);
export function normalizeFeedback(input) {
  if(!plain(input))return fail('問卷內容格式不完整，請重新確認');
  if(Object.keys(input).some(k=>!FIELD_ORDER.includes(k)))return fail('問卷欄位已變更，請重新開啟');
  const answer={};
  for(const key of FIELD_ORDER){
    const value=input[key];
    if(key==='activities'){
      if(!Array.isArray(value)||value.length<1||value.length>3||new Set(value).size!==value.length||value.some(v=>!OPTIONS.activities.some(([id])=>id===v))||(value.includes('none')&&value.length>1))return fail('想嘗試的安排請選 1 至 3 項，暫不增加須單獨選');
      answer[key]=OPTIONS.activities.map(([id])=>id).filter(id=>value.includes(id));
    }else if(OPTIONS[key]){
      if(!OPTIONS[key].some(([id])=>id===value))return fail('請完成「'+FIELD_LABELS[key]+'」');
      answer[key]=value;
    }else if(RATING_QUESTIONS.some(([id])=>id===key)){
      if(!RATING_OPTIONS.some(([id])=>id===value))return fail('請完成「'+FIELD_LABELS[key]+'」');
      answer[key]=value;
    }else{
      if(value!==undefined&&typeof value!=='string')return fail('文字欄位格式不正確');
      const text=(value||'').trim();if(text.length>(key==='memberName'?60:600))return fail('「'+FIELD_LABELS[key]+'」超過字數上限');
      answer[key]=text;
    }
  }
  return answer;
}
export function answerLabel(key,value){
  if(Array.isArray(value))return value.map(v=>answerLabel(key,v)).join('、');
  const options=OPTIONS[key]||(RATING_QUESTIONS.some(([id])=>id===key)?RATING_OPTIONS:null);
  if(options)return options.find(([id])=>id===value)?.[1]||'無法辨識';
  return value||(key==='memberName'?'未留姓名':'未填');
}
export function feedbackSummary(rows){
  const total=rows.length;
  const ratings=Object.fromEntries(RATING_QUESTIONS.map(([key])=>{
    const counts=Object.fromEntries(RATING_OPTIONS.map(([id])=>[id,0]));
    for(const row of rows)counts[row.answers[key]]++;
    const valid=total-counts.na;
    return [key,{counts,valid,unavailable:counts.na,agree:counts['4']+counts['5'],agreePercent:valid?Math.round((counts['4']+counts['5'])/valid*100):null}];
  }));
  const choices=Object.fromEntries(Object.entries(OPTIONS).map(([key,options])=>[key,options.map(([id,label])=>({id,label,count:rows.filter(row=>[].concat(row.answers[key]).includes(id)).length}))]));
  return {total,ratings,choices};
}
